import fs from 'node:fs';
const M='/workspace/oscraft/scenarios/moba/';
const props=JSON.parse(fs.readFileSync(M+'assets/props.json','utf8'));
const kindOf=(k)=>k.replace(/-/g,'_');
const kinds=['pillar-rock-1-skinned','pillar-rock-2-skinned','pillar-rock-3-skinned','pillar-rock-4-skinned','pillar-rock-5-skinned','pillar-rock-6-skinned'];
for (const k of kinds) {
  const key=kindOf(k);
  const path=props[key]||props[k];
  const exists=path?fs.existsSync(M+'assets/'+path):false;
  console.log(k,'->','key='+key,'path='+path,'modelExists='+exists);
}
const names=fs.readFileSync(M+'0_names.osd','utf8');
const list=/prop_kinds\(\[([\s\S]*?)\]\)/.exec(names)[1].split(',').map((s)=>s.trim().replace(/^"|"$/g,''));
console.log('prop_kinds count', list.length);
for (const k of kinds) console.log(k, 'in prop_kinds at index', list.indexOf(k));
const assets=JSON.parse(fs.readFileSync(M+'assets/assets.json','utf8'));
const items=assets.items||[];
for (const k of kinds) { const it=items.find((i)=>i.path&&i.path.endsWith(k+'.glb')); console.log(k,'assets.json entry role='+(it?it.role:'MISSING')); }
const sizes=JSON.parse(fs.readFileSync(M+'assets/prop_sizes.json','utf8'));
console.log('sizes', kinds.map((k)=>k+'='+sizes[k]).join(' '));
